attribute vec3 aO; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU;
    void main(){ float u = uTime - aT; if (u < 0. || u > 0.40){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float k = 1. - pow(1. - clamp(u/.3, 0., 1.), 2.), S = .34*mix(1.35, .8, k);   /* contracts inward on the body */
      vec4 mv = viewMatrix*vec4(aO, 1.); mv.xyz += normalize(-mv.xyz)*.28; mv.xy += position.xy*S; vP = position.xy*1.05; vU = u; gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      float r = length(vP), a = atan(vP.y, vP.x), lum = 0., hot = 0.;
      for (int i=0;i<3;i++){
        float fi = float(i), R = .88 - fi*.2, w = .02 - fi*.003;
        float dash = fi < .5 ? 1. : smoothstep(.1, .35, abs(sin(a*(3. + fi) + fi*1.7)));   // inner rings break into arcs
        float ring = exp(-pow(abs(r - R)/w, 2.4))*dash;
        lum += ring*(1. - fi*.25); hot += lcore(r - R, w*.3)*dash*.5;
      }
      float f = (vU < .033 ? 1.6 : 1.)*(1. - smoothstep(.18, 0.40, vU));   // 2-frame peak, contracts, fades
      vec3 o = (mix(uOrange, uGold, .55)*lum + mix(uGold, vec3(1., .96, .88), .6)*hot)*f*1.3*smoothstep(1.05, .95, r);
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.);
    }

